function buildBody(spec: DraftSpec, moneyPage: { label: string; href: string }, supportingPages: { label: string; href: string }[]) {
  const practical = spec.practical.map((item, index) => `${index + 1}. ${item}`).join(" ");
  const avoid = spec.avoid.map((item) => `• ${item}`).join(" ");
  const support = supportingPages.map((item) => `${item.label} (${item.href})`).join("; ");

  return [
    spec.opening,
    `Що важливо розуміти. ${spec.mechanism} Один і той самий зовнішній прояв може мати різні причини, тому стаття не використовується для самодіагностики. У медичній дерматології та естетичній медицині рішення залежить від анамнезу, огляду, активності процесу, стану шкірного бар’єра, попередніх процедур і того, як змінювалися симптоми з часом.`,
    `Практичний орієнтир. ${practical} Ці кроки допомагають підготуватися до консультації та не втратити важливі деталі. Вони не замінюють персональні призначення і не означають, що кожній людині потрібні однакові аналізи, косметика, препарати або процедури.`,
    `Чого краще не робити самостійно. ${avoid} Особливо небажано різко змінювати кілька засобів або процедур одночасно: тоді складніше зрозуміти, що саме покращило або погіршило стан. Якщо вже є призначене лікування, не скасовуйте його через інформацію з інтернету без розмови з лікарем, який знає ваш медичний контекст.`,
    `Коли потрібна професійна оцінка. ${spec.doctorRoute} Під час консультації спеціаліст уточнює перебіг симптомів, попередній догляд і лікування, оцінює шкіру або волосся та визначає, чи потрібні додаткові методи діагностики. Мета консультації — не “підібрати процедуру за назвою проблеми”, а зрозуміти задачу і вибрати найбільш доречний та безпечний маршрут.`,
    `Де продовжити на RESET Clinic. Основна профільна сторінка для цього запиту — ${moneyPage.label} (${moneyPage.href}). Додатково корисні пов’язані матеріали: ${support}. Перехід між інформаційною статтею, problem/service page та профілем лікаря допомагає відокремити загальну освіту від персонального медичного рішення.`,
    `Матеріал підготовлений як редакційний медичний draft. Перед індексацією RESET Clinic має підтвердити фактичність формулювань, автора, лікаря-рецензента, дату медичної перевірки та відповідність рекомендацій реальним послугам клініки. Якщо симптоми швидко прогресують, супроводжуються вираженим болем, набряком, кровотечею, загальним погіршенням самопочуття або іншими тривожними ознаками, потрібна очна медична оцінка, а не очікування ефекту від домашнього догляду.`,
  ].join("\n\n");
}

